    p = max(p, 1.0 / len(null_vals))
    print(f"{name:50s} | Obs={t_obs:.3f} | Null={m_null:.3f} +/- {s_null:.3f} | z={z:+.2f} | p={p:.4f} | time={dt:.2f}s")

